// 1번 카드가 맨 위인 카드 n장: 맨 위를 버리고, 그다음 맨 위를 맨 아래로 옮긴다
queue<int> q;
for (int i = 1; i <= n; i++) q.push(i);
while (q.size() > 1) {
    q.pop();                       // 버리기
    q.push(q.front()); q.pop();    // 맨 아래로 옮기기
}
// 남은 카드는 q.front()

